import{bV as e,aL as o,u as r,G as t}from"./chunks/framework.BfzMay2U.js";const g=JSON.parse('{"title":"制造业 PHP 面试题：UniApp、小程序与 APP（101—125）","description":"","frontmatter":{"title":"制造业 PHP 面试题：UniApp、小程序与 APP（101—125）","date":"2026-11-15T10:40:00.000Z","categories":["面试","PHP"],"tags":["UniApp","微信小程序","APP","扫码报工","离线同步"],"sidebarSort":5},"headers":[],"relativePath":"php/jd/uniapp-mobile-interview.md","filePath":"php/jd/uniapp-mobile-interview.md"}'),n={name:"php/jd/uniapp-mobile-interview.md"};function p(i,a,s,h,l,d){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="制造业-php-面试题-uniapp、小程序与-app-101—125" tabindex="-1">制造业 PHP 面试题：UniApp、小程序与 APP（101—125） <a class="header-anchor" href="#制造业-php-面试题-uniapp、小程序与-app-101—125" aria-label="Permalink to &quot;制造业 PHP 面试题：UniApp、小程序与 APP（101—125）&quot;">​</a></h1><p>车间移动端的重点是扫码操作、网络波动、重复提交、身份归属和错误恢复。本篇以工单查询、扫码报工、质量拍照和离线补传为主线。</p><div class="info custom-block"><p class="custom-block-title">平台边界</p><p>UniApp 提供跨端开发能力，但不代表所有平台 API、权限、存储和后台能力相同。以下回答需结合项目使用的 Vue 版本、运行端、原生插件及平台文档验证。</p></div><h2 id="一、页面与跨端开发" tabindex="-1">一、页面与跨端开发 <a class="header-anchor" href="#一、页面与跨端开发" aria-label="Permalink to &quot;一、页面与跨端开发&quot;">​</a></h2><h3 id="_101-为什么选择-uniapp-它有哪些限制" tabindex="-1">101. 为什么选择 UniApp？它有哪些限制？ <a class="header-anchor" href="#_101-为什么选择-uniapp-它有哪些限制" aria-label="Permalink to &quot;101. 为什么选择 UniApp？它有哪些限制？&quot;">​</a></h3><p><strong>参考回答：</strong> 可以复用 Vue 体系下的页面、业务状态和请求逻辑，覆盖小程序、APP 等目标端，降低多端维护成本。但渲染机制、组件支持、权限、原生能力和发布方式有差异，必须围绕实际目标端验证，而非承诺一份代码完全无差异运行。</p><p><strong>追问要点：</strong> 先确认使用传统 UniApp 还是其他产品形态，以及 Vue、构建工具和端版本，不能混用不同文档中的能力。</p><h3 id="_102-uniapp-和普通-vue-web-项目有什么不同" tabindex="-1">102. UniApp 和普通 Vue Web 项目有什么不同？ <a class="header-anchor" href="#_102-uniapp-和普通-vue-web-项目有什么不同" aria-label="Permalink to &quot;102. UniApp 和普通 Vue Web 项目有什么不同？&quot;">​</a></h3><p><strong>参考回答：</strong> 业务响应式思路可以复用，但页面组件、路由、生命周期和平台 API 有额外约束。DOM、浏览器插件、Cookie 和 Web 存储的假设未必在小程序或原生端成立，应使用项目约定的跨端能力并保留必要的平台适配。</p><p><strong>追问要点：</strong> 不能把依赖浏览器 DOM 的 UI 库直接当成跨端组件库；性能优化也要看目标平台实际渲染和通信成本。</p><h3 id="_103-onload、onshow、onready-适合做什么" tabindex="-1">103. <code>onLoad</code>、<code>onShow</code>、<code>onReady</code> 适合做什么？ <a class="header-anchor" href="#_103-onload、onshow、onready-适合做什么" aria-label="Permalink to &quot;103. `onLoad`、`onShow`、`onReady` 适合做什么？&quot;">​</a></h3><p><strong>参考回答：</strong> <code>onLoad</code> 通常处理页面初次加载参数与初始化，<code>onShow</code> 在页面显示时触发，适合按需检查返回后的数据变化，<code>onReady</code> 适合依赖首次渲染完成的操作。组件钩子和页面钩子应按所用版本及组件类型使用。</p><p><strong>追问要点：</strong> 每次 <code>onShow</code> 都无条件请求所有接口，会导致重复加载；应结合失效标记和请求去重，离开页面后还要清理监听与定时器。</p><h3 id="_104-工单列表、详情和报工页面之间怎样传数据" tabindex="-1">104. 工单列表、详情和报工页面之间怎样传数据？ <a class="header-anchor" href="#_104-工单列表、详情和报工页面之间怎样传数据" aria-label="Permalink to &quot;104. 工单列表、详情和报工页面之间怎样传数据？&quot;">​</a></h3><p><strong>参考回答：</strong> 路由传稳定标识，详情页面从接口读取权威数据；跨页面共享的身份和必要状态使用项目现有状态管理。不要把整份工单 JSON 或可篡改的权限结果放在 URL 中，并在提交前重新验证服务端状态。</p><p><strong>追问要点：</strong> 返回列表可通过明确的刷新标记或既有事件机制更新，避免用多个全局变量维持不清晰的页面关系。</p><h3 id="_105-列表加载更多、筛选和搜索如何避免数据错乱" tabindex="-1">105. 列表加载更多、筛选和搜索如何避免数据错乱？ <a class="header-anchor" href="#_105-列表加载更多、筛选和搜索如何避免数据错乱" aria-label="Permalink to &quot;105. 列表加载更多、筛选和搜索如何避免数据错乱？&quot;">​</a></h3><p><strong>参考回答：</strong> 筛选条件改变时重置分页和数据，区分首次加载、刷新与追加的状态。为请求设置序号或取消旧请求，避免旧搜索结果覆盖新条件；追加时按业务 ID 去重，并根据后端分页契约判断是否还有数据。</p><p><strong>追问要点：</strong> 游标应和当前筛选绑定，不能把 A 工厂最后一页的游标用于 B 工厂；请求失败后保留可恢复的界面和重试入口。</p><h3 id="_106-请求封装应统一哪些内容" tabindex="-1">106. 请求封装应统一哪些内容？ <a class="header-anchor" href="#_106-请求封装应统一哪些内容" aria-label="Permalink to &quot;106. 请求封装应统一哪些内容？&quot;">​</a></h3><p><strong>参考回答：</strong> 统一服务地址、认证头、超时、请求 ID、响应解析和错误分类，页面仍决定具体业务交互。区分网络失败、HTTP 错误和业务冲突，不对所有 POST 自动重试，也不要每个失败同时弹出多个提示。</p><p><strong>追问要点：</strong> <code>uni.request</code> 的成功回调说明收到响应，不代表 HTTP 状态或业务结果成功；还要检查状态码及明确的响应字段。</p><h3 id="_107-微信小程序登录为什么不能把-code-当用户身份" tabindex="-1">107. 微信小程序登录为什么不能把 <code>code</code> 当用户身份？ <a class="header-anchor" href="#_107-微信小程序登录为什么不能把-code-当用户身份" aria-label="Permalink to &quot;107. 微信小程序登录为什么不能把 `code` 当用户身份？&quot;">​</a></h3><p><strong>参考回答：</strong> 登录 <code>code</code> 是临时凭证，应交给后端与微信服务交换所需身份信息，再映射企业员工并签发业务登录凭证。微信身份不自动等于公司授权，仍需处理员工绑定、账号停用、工厂和岗位权限。</p><p><strong>追问要点：</strong> AppSecret 和平台会话密钥不放到客户端；不能相信客户端直接传来的 <code>openid</code> 或员工 ID 就完成登录。</p><h3 id="_108-多个请求同时遇到-token-过期怎么办" tabindex="-1">108. 多个请求同时遇到 Token 过期怎么办？ <a class="header-anchor" href="#_108-多个请求同时遇到-token-过期怎么办" aria-label="Permalink to &quot;108. 多个请求同时遇到 Token 过期怎么办？&quot;">​</a></h3><p><strong>参考回答：</strong> 采用单次刷新协调：第一个请求执行刷新，其余等待同一结果；刷新成功后仅对允许安全重放的请求进行一次重放。刷新失败清理登录态并引导重新认证，防止刷新接口再次触发无限递归。</p><p><strong>追问要点：</strong> 业务写入重放要复用原幂等键；不能把所有 401 都认为可刷新，停用账号和权限撤销可能需要立即终止会话。</p><h3 id="_109-小程序和-app-中的-token-如何存储" tabindex="-1">109. 小程序和 APP 中的 Token 如何存储？ <a class="header-anchor" href="#_109-小程序和-app-中的-token-如何存储" aria-label="Permalink to &quot;109. 小程序和 APP 中的 Token 如何存储？&quot;">​</a></h3><p><strong>参考回答：</strong> 按平台能力和风险选择存储，控制凭证有效期及撤销能力，不在日志和错误上报中输出明文。普通持久化存储不是天然安全保险箱，APP 如需较高保障可使用经过验证的系统安全存储方案；客户端不保存用户登录密码。</p><p><strong>追问要点：</strong> 服务端始终执行授权，共享终端换账号时清除或隔离缓存、草稿和附件，防止上一人的数据被下一人看到。</p><h3 id="_110-扫码报工如何处理错误码和恶意输入" tabindex="-1">110. 扫码报工如何处理错误码和恶意输入？ <a class="header-anchor" href="#_110-扫码报工如何处理错误码和恶意输入" aria-label="Permalink to &quot;110. 扫码报工如何处理错误码和恶意输入？&quot;">​</a></h3><p><strong>参考回答：</strong> 按业务定义解析码类型、格式和长度，区分工单码、物料码和批次码，再到服务端校验有效性、归属及状态。扫码内容作为外部输入处理，不能扫描任意 URL 就自动跳转、下载或执行指令。</p><p><strong>追问要点：</strong> 连续扫码要考虑相机回调重复、焦点与节流，但服务端仍需幂等。对过期、错工单和跨工厂的码给出具体可操作提示。</p><h2 id="二、离线与同步" tabindex="-1">二、离线与同步 <a class="header-anchor" href="#二、离线与同步" aria-label="Permalink to &quot;二、离线与同步&quot;">​</a></h2><h3 id="_111-报工页面怎样避免重复提交" tabindex="-1">111. 报工页面怎样避免重复提交？ <a class="header-anchor" href="#_111-报工页面怎样避免重复提交" aria-label="Permalink to &quot;111. 报工页面怎样避免重复提交？&quot;">​</a></h3><p><strong>参考回答：</strong> 按一次业务操作生成稳定 <code>client_request_id</code>，提交时锁定交互并保存待处理状态；网络重试、页面重进和状态查询继续使用原键。服务端通过唯一约束和事务返回同一次操作结果，按钮防抖只减少误触。</p><p><strong>追问要点：</strong> 用户想新建第二次报工才生成新键；编辑未提交草稿和更改已发送请求是不同动作，同键不同内容必须识别为冲突。</p><h3 id="_112-离线功能能做到-和在线完全一样-吗" tabindex="-1">112. 离线功能能做到“和在线完全一样”吗？ <a class="header-anchor" href="#_112-离线功能能做到-和在线完全一样-吗" aria-label="Permalink to &quot;112. 离线功能能做到“和在线完全一样”吗？&quot;">​</a></h3><p><strong>参考回答：</strong> 不能。离线端无法可靠知道最新库存、权限、质量状态和工艺变更，应限制为允许离线采集的动作，保存草稿或待同步记录，最终由服务端确认。质量放行等高风险动作通常需要在线校验，具体按批准规则确定。</p><p><strong>追问要点：</strong> 离线展示要区分“已本地保存”与“已服务端确认”，并显示缓存时间和待同步数量，避免现场人员误以为已入账。</p><h3 id="_113-小程序和-app-的离线数据都可以直接用-sqlite-吗" tabindex="-1">113. 小程序和 APP 的离线数据都可以直接用 SQLite 吗？ <a class="header-anchor" href="#_113-小程序和-app-的离线数据都可以直接用-sqlite-吗" aria-label="Permalink to &quot;113. 小程序和 APP 的离线数据都可以直接用 SQLite 吗？&quot;">​</a></h3><p><strong>参考回答：</strong> 不能这样假设。小程序通常使用平台提供的本地存储和文件能力，并受容量与生命周期限制；APP 可根据运行环境使用 SQLite 等原生能力，需核对 API、插件和真机支持。共享业务模型可复用，存储实现按平台选择。</p><p><strong>追问要点：</strong> 小程序同步存储会阻塞当前执行，较多读写可评估异步 API。无论平台，都需验证写入失败、空间不足、数据升级和卸载清理行为。</p><h3 id="_114-本地待同步队列最少需要哪些字段" tabindex="-1">114. 本地待同步队列最少需要哪些字段？ <a class="header-anchor" href="#_114-本地待同步队列最少需要哪些字段" aria-label="Permalink to &quot;114. 本地待同步队列最少需要哪些字段？&quot;">​</a></h3><p><strong>参考回答：</strong> 稳定请求 ID、所属账号和工厂、操作类型、payload 版本、内容、创建时间、同步状态、尝试次数及最后错误。对存在依赖的记录保留关联 ID，附件单独记录上传状态，不能只存一段 JSON 就不知道处理进度。</p><p><strong>追问要点：</strong> 持久化成功后才提示本地已保存，读取恢复时先校验结构和版本。敏感信息按最小化原则保存，并定义本地保留和清理策略。</p><h3 id="_115-待同步、处理中、成功、冲突应怎样流转" tabindex="-1">115. 待同步、处理中、成功、冲突应怎样流转？ <a class="header-anchor" href="#_115-待同步、处理中、成功、冲突应怎样流转" aria-label="Permalink to &quot;115. 待同步、处理中、成功、冲突应怎样流转？&quot;">​</a></h3><p><strong>参考回答：</strong> 待同步由同步器领取后转处理中；明确成功后记录服务端单号；网络或临时错误回到可重试状态；库存、工单版本等业务冲突进入待人工处理。APP 崩溃留下的处理中任务应通过超时恢复及服务端查询确认结果。</p><p><strong>追问要点：</strong> 删除本地记录前确保已获得最终业务结果，并按需要保留回执；不能收到 HTTP 200 就立即清空全部待同步数据。</p><h3 id="_116-手机显示有网络-为什么同步仍可能失败" tabindex="-1">116. 手机显示有网络，为什么同步仍可能失败？ <a class="header-anchor" href="#_116-手机显示有网络-为什么同步仍可能失败" aria-label="Permalink to &quot;116. 手机显示有网络，为什么同步仍可能失败？&quot;">​</a></h3><p><strong>参考回答：</strong> 网络状态只说明部分连接条件，可能遇到内网未连通、认证门户、DNS、TLS、代理或服务不可达。同步以实际接口结果为准，使用合理超时、有限重试和清晰错误提示，网络恢复事件只是触发重试的信号。</p><p><strong>追问要点：</strong> 不要每秒无限探测所有任务，也不要在网络切换时生成新业务键；控制并发和退避，避免恢复后集中压垮服务端。</p><h3 id="_117-离线期间工单关闭或库存不足了-客户端怎么办" tabindex="-1">117. 离线期间工单关闭或库存不足了，客户端怎么办？ <a class="header-anchor" href="#_117-离线期间工单关闭或库存不足了-客户端怎么办" aria-label="Permalink to &quot;117. 离线期间工单关闭或库存不足了，客户端怎么办？&quot;">​</a></h3><p><strong>参考回答：</strong> 服务端拒绝不再满足条件的动作并返回冲突类型、当前状态及可选处理方式；客户端展示原始待提交内容，让授权人员修改、转单、取消或走补录审批。不能自动覆盖新状态或强制扣成负库存。</p><p><strong>追问要点：</strong> 原始采集时间保留，但不能把设备时间当成绕过工单关闭规则的依据。修改内容后使用契约允许的新操作或修订关系。</p><h3 id="_118-换账号、token-失效时-离线记录由谁提交" tabindex="-1">118. 换账号、Token 失效时，离线记录由谁提交？ <a class="header-anchor" href="#_118-换账号、token-失效时-离线记录由谁提交" aria-label="Permalink to &quot;118. 换账号、Token 失效时，离线记录由谁提交？&quot;">​</a></h3><p><strong>参考回答：</strong> 本地记录绑定原操作者与组织，换账号不应悄悄用新账号提交旧记录。需要原用户重新认证后同步，或按授权的交接、复核流程处理，保留实际采集者、提交者和原因。界面应明确提示尚有待处理记录。</p><p><strong>追问要点：</strong> 不能因为怕数据丢失就在退出时不受控地暴露旧账号草稿，也不能默认清空所有生产记录；按既定策略处理并明确结果。</p><h3 id="_119-app-退到后台或小程序关闭后-还能保证继续同步吗" tabindex="-1">119. APP 退到后台或小程序关闭后，还能保证继续同步吗？ <a class="header-anchor" href="#_119-app-退到后台或小程序关闭后-还能保证继续同步吗" aria-label="Permalink to &quot;119. APP 退到后台或小程序关闭后，还能保证继续同步吗？&quot;">​</a></h3><p><strong>参考回答：</strong> 不能承诺。操作系统与平台会限制或终止后台执行，应先持久化队列，在再次启动、回到前台或具备允许能力时恢复；真正需要持续采集的任务通常由稳定网关或服务器承担。</p><p><strong>追问要点：</strong> 进程被杀、设备关机和应用升级后都应测试队列恢复；仅注册网络监听器不能保证关闭后的后台上传。</p><h3 id="_120-本地创建记录和上传附件有依赖时-怎样安排" tabindex="-1">120. 本地创建记录和上传附件有依赖时，怎样安排？ <a class="header-anchor" href="#_120-本地创建记录和上传附件有依赖时-怎样安排" aria-label="Permalink to &quot;120. 本地创建记录和上传附件有依赖时，怎样安排？&quot;">​</a></h3><p><strong>参考回答：</strong> 使用稳定关联 ID 表达主记录与附件关系，按接口契约先取得上传标识或先创建草稿，全部必要附件完整后再提交确认。每一步可查询、可重试，服务端不能把缺附件的半成品误认为质量记录完成。</p><p><strong>追问要点：</strong> 清理孤立附件前确认其未被有效记录引用；附件修改后应更新对应版本和摘要，不能继续绑定旧签署记录。</p><h2 id="三、真机能力、性能与发布" tabindex="-1">三、真机能力、性能与发布 <a class="header-anchor" href="#三、真机能力、性能与发布" aria-label="Permalink to &quot;三、真机能力、性能与发布&quot;">​</a></h2><h3 id="_121-图片上传失败、文件过大和拍照权限被拒绝怎么处理" tabindex="-1">121. 图片上传失败、文件过大和拍照权限被拒绝怎么处理？ <a class="header-anchor" href="#_121-图片上传失败、文件过大和拍照权限被拒绝怎么处理" aria-label="Permalink to &quot;121. 图片上传失败、文件过大和拍照权限被拒绝怎么处理？&quot;">​</a></h3><p><strong>参考回答：</strong> 拍照或选择文件前后处理平台权限与用户取消，校验类型和大小，按业务允许的清晰度压缩，并提供进度与可恢复失败状态。服务端重新校验，重要原始证据是否允许压缩需事先明确，不能默认丢弃原件。</p><p><strong>追问要点：</strong> 前端限制不能代替服务端检查；分片上传要验证组装、摘要和权限，重复上传不应生成无法管理的大量附件。</p><h3 id="_122-小程序接口在开发工具能用-真机失败怎么办" tabindex="-1">122. 小程序接口在开发工具能用，真机失败怎么办？ <a class="header-anchor" href="#_122-小程序接口在开发工具能用-真机失败怎么办" aria-label="Permalink to &quot;122. 小程序接口在开发工具能用，真机失败怎么办？&quot;">​</a></h3><p><strong>参考回答：</strong> 检查合法请求域名、HTTPS 证书和完整链、平台限制、登录环境、网络路由及上传下载域名配置。开发工具跳过校验的设置不能证明正式版本可用，应记录真机错误并与服务端访问日志对应。</p><p><strong>追问要点：</strong> <code>localhost</code> 指向设备自身，电脑可访问的内网地址手机未必可访问；开发、体验和正式版还可能使用不同配置。</p><h3 id="_123-长列表、扫码页面卡顿应怎样优化" tabindex="-1">123. 长列表、扫码页面卡顿应怎样优化？ <a class="header-anchor" href="#_123-长列表、扫码页面卡顿应怎样优化" aria-label="Permalink to &quot;123. 长列表、扫码页面卡顿应怎样优化？&quot;">​</a></h3><p><strong>参考回答：</strong> 先通过真机观察渲染、请求和内存，列表分页并减少不必要字段，使用稳定 key，避免频繁更新巨大响应式对象。扫码回调做适度节流，图片使用合适尺寸，离开页面清理监听和相机相关资源。</p><p><strong>追问要点：</strong> 虚拟列表是否适配目标端要验证，不能只看浏览器表现；优化后记录首屏、滚动、连续扫码和低端机数据。</p><h3 id="_124-条件编译和平台适配代码怎样组织" tabindex="-1">124. 条件编译和平台适配代码怎样组织？ <a class="header-anchor" href="#_124-条件编译和平台适配代码怎样组织" aria-label="Permalink to &quot;124. 条件编译和平台适配代码怎样组织？&quot;">​</a></h3><p><strong>参考回答：</strong> 把扫描、存储、权限等确有差异的操作放在清楚的边界，使用项目已有的平台适配和条件编译模式，页面复用业务流程。不要在每个组件里散落大量平台判断，也不为从未支持的平台设计框架。</p><p><strong>追问要点：</strong> 编译通过不代表运行正确，各目标端至少验证登录、核心页面、权限拒绝和提交恢复；原生插件还需验证包配置与版本兼容。</p><h3 id="_125-小程序与-app-发布上线各要注意什么" tabindex="-1">125. 小程序与 APP 发布上线各要注意什么？ <a class="header-anchor" href="#_125-小程序与-app-发布上线各要注意什么" aria-label="Permalink to &quot;125. 小程序与 APP 发布上线各要注意什么？&quot;">​</a></h3><p><strong>参考回答：</strong> 小程序关注 AppID、环境地址、合法域名、隐私权限、体验版与审核发布；APP 关注包标识、签名证书、权限说明、原生插件、分发和版本兼容。后端在旧客户端仍运行时保持约定兼容，并明确最低支持版本和升级策略。</p><p><strong>追问要点：</strong> 发布前验证生产配置、账号与数据隔离、离线队列升级和回退路径。热更新不能绕过平台规则、原生能力限制及企业变更要求。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./mes-edhr-oa-interview.html">上一篇：MES、E-DHR 与 OA（76—100）</a></li><li><a href="./delivery-troubleshooting-interview.html">下一篇：测试、上线与需求协作（126—150）</a></li><li><a href="./../">返回 PHP 面试指南</a></li><li><a href="https://uniapp.dcloud.net.cn/api/storage/storage.html" target="_blank" rel="noreferrer">UniApp 本地存储</a></li><li><a href="https://www.html5plus.org/doc/zh_cn/sqlite.html" target="_blank" rel="noreferrer">HTML5 Plus SQLite（APP 相关能力）</a></li><li><a href="https://uniapp.dcloud.net.cn/api/request/request.html" target="_blank" rel="noreferrer">UniApp 请求 API</a></li></ul>',83)])])}const u=e(n,[["render",p]]);export{g as __pageData,u as default};
